+import { Api } from './api';
+import { log } from './log';
+
+/**
+ * Lifts the hold on a pull request once its last blocking thread is resolved. While the
+ * record says `held`, the approval check withholds approval. The next push rewrites the
+ * record from the open threads.
+ */
+export async function liftHold(api: Api, pr: number, threadId: string): Promise<void> {
+  await api.resolveThread(threadId);
+  try {
+    await api.updateRecord(pr, { held: false });
+  } catch (error) {
+    log.warning(`Could not update the record of #${pr}, retrying once: ${error}`);
+    await api.updateRecord(pr, { held: false }).catch(() => undefined);
+  }
+}
